ALTER TYPE "CarStatus" ADD VALUE 'NEEDS_INFO';
ALTER TYPE "SlotType" ADD VALUE 'LEFT_DOOR';
ALTER TYPE "SlotType" ADD VALUE 'RIGHT_DOOR';
ALTER TYPE "SlotType" ADD VALUE 'REAR_BODY';
ALTER TABLE "users" ADD COLUMN "verificationRequired" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "locale" TEXT NOT NULL DEFAULT 'ru';
ALTER TABLE "cars" ADD COLUMN "modelAssetId" UUID, ADD COLUMN "modelHotspots" JSONB;
ALTER TABLE "media_assets" ADD COLUMN "kind" TEXT NOT NULL DEFAULT 'PHOTO', ADD COLUMN "contentType" TEXT NOT NULL DEFAULT 'image/jpeg';
CREATE UNIQUE INDEX "cars_modelAssetId_key" ON "cars"("modelAssetId");
ALTER TABLE "cars" ADD CONSTRAINT "cars_modelAssetId_fkey" FOREIGN KEY ("modelAssetId") REFERENCES "media_assets"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "EmailChallenge" ("userId" TEXT PRIMARY KEY, "codeHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "sentAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "EmailChallenge" ADD CONSTRAINT "EmailChallenge_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "RateBucket" ("key" TEXT PRIMARY KEY, "count" INTEGER NOT NULL DEFAULT 1, "expiresAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ModerationMessage" ("id" TEXT PRIMARY KEY, "carId" TEXT NOT NULL, "status" "CarStatus" NOT NULL, "body" TEXT NOT NULL, "emailStatus" TEXT NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "ModerationMessage" ADD CONSTRAINT "ModerationMessage_carId_fkey" FOREIGN KEY ("carId") REFERENCES "cars"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE INDEX "ModerationMessage_carId_createdAt_idx" ON "ModerationMessage"("carId", "createdAt");
CREATE TABLE "CarView" ("carId" TEXT NOT NULL, "buyerId" TEXT NOT NULL, "viewedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("carId", "buyerId"));
ALTER TABLE "CarView" ADD CONSTRAINT "CarView_carId_fkey" FOREIGN KEY ("carId") REFERENCES "cars"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CarView" ADD CONSTRAINT "CarView_buyerId_fkey" FOREIGN KEY ("buyerId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
